-- References between loaded norms (stubs left out) and how many point at a missing item. Read only.
SELECT S.AGREEMENT_ID, S.TO_AGREEMENT_ID, COUNT(*) N,
 SUM(CASE WHEN S.TO_AGREEMENT_ITEM_SEQ_ID IS NOT NULL AND NOT EXISTS (SELECT 1 FROM AGREEMENT_ITEM P WHERE P.AGREEMENT_ID=S.TO_AGREEMENT_ID AND P.AGREEMENT_ITEM_SEQ_ID=S.TO_AGREEMENT_ITEM_SEQ_ID) THEN 1 ELSE 0 END) DANGLING
FROM AGREEMENT_ASSOC S WHERE S.AGREEMENT_ID <> S.TO_AGREEMENT_ID AND S.TO_AGREEMENT_ID NOT LIKE 'STUB-%' GROUP BY S.AGREEMENT_ID, S.TO_AGREEMENT_ID
